INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64091552', 64091552, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL BINA ADMINISTRASI KEWILAYAHAN', 'Tenaga Ahli Pengolah Data Pengendalian Kinerja Pelaksanaan Tugas dan Wewenang Gubernur Sebagai Wakil Pemerintah Pusat', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 93500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan evaluasi secara komprehensif terhadap pelaksanaan peran Gubernur sebagai Wakil Pemerintah Pusat (GWPP), sekaligus menyusun analisis kebijakan yang dapat menjadi dasar dalam merumuskan model ideal kewenangan dan kelembagaan GWPP yang lebih efektif, adaptif, dan responsif terhadap dinamika penyelenggaraan pemerintahan pusat dan daerah. 2. Menganalisis kesesuaian regulasi, kewenangan, dan kelembagaan GWPP dengan kebutuhan tata kelola pemerintahan pusat-daerah saat ini. 3. Mengidentifikasi permasalahan, kendala, serta kesenjangan dalam implementasi peran GWPP di berbagai daerah. 4. Merumuskan model ideal kewenangan dan kelembagaan GWPP yang mampu memperkuat fungsi koordinasi, pembinaan, pengawasan, serta fasilitasi penyelenggaraan pemerintahan daerah. 5. Menyusun rekomendasi kebijakan strategis yang dapat digunakan oleh Kementerian Dalam Negeri maupun pemerintah daerah provinsi untuk meningkatkan efektivitas peran GWPP. 6. Mendukung terwujudnya sinergi pusat-daerah dalam pelaksanaan kebijakan nasional tanpa mengurangi prinsip otonomi daerah.', '1. Tersusunnya dokumen pelaksanaan 7 tugas dan wewenang Gubernur sebagai Wakil Pemerintah Pusat, termasuk capaian, hambatan, serta kesenjangan yang terjadi. 2. Tersusunnya laporan Pembinaan dan Pengawasan pelaksanaan 7 tugas dan wewenang Gubernur sebagai Wakil Pemerintah Pusat 3. Tercapainya kinerja perangkat gubernur yang optimal sesuai dengan ketentuan peraturan perundang-undangan 4. Terlaksananya target realisasi keuangan dan kinerja Dekonsentrasi Gubernur sebagai Wakil Pemerintah Pusat secara optimal baik dari sisi anggaran dan kinerja', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1329631);
